// Shares this flow's settings with the CI/CD flow (env variables are only visible
// inside their own tab, so they are copied into a global variable).
// Runs at every start/deploy of this flow, so a new login from GitHub takes effect right away.
const login = { username: env.get("TB_USERNAME"), password: env.get("TB_PASSWORD") };
if (!login.username || !login.password) {
    node.status({fill:"red", shape:"ring", text:"TB_USERNAME / TB_PASSWORD not set"});
    node.error("Fill in TB_USERNAME and TB_PASSWORD in the Fleet config tab's environment variables");
    return null;
}
global.set("tb_login", login);
node.status({fill:"green", shape:"dot", text:"ThingsBoard login shared " + new Date().toLocaleString()});
return null;
